function lintEntry(entry: Record<string, string>): string[] {
  const keys = Object.keys(entry);
  const problems: string[] = [];
  if (keys.includes("types") && keys[0] !== "types") problems.push("types must be first");
  if (keys.includes("default") && keys.at(-1) !== "default") problems.push("default must be last");
  return problems;
}

const entries: Record<string, string>[] = [
