  ".": { types: "./dist/index.d.ts", default: "./dist/index.js" },
  "./parse": { types: "./dist/parse.d.ts", default: "./dist/parse.js" },
};

const published = new Set(tarball);
const missing: string[] = [];
for (const [subpath, conditions] of Object.entries(exportsMap)) {
  for (const [condition, target] of Object.entries(conditions)) {
    if (!published.has(target.replace(/^\.\//, ""))) missing.push(`${subpath} ${condition} ${target} is not published`);
  }
}
console.log(missing.length ? missing.join("\n") : "all targets published");

