type Change = string;

const BREAKING = new Set(["remove-export", "required-input-property", "wider-return", "narrower-parameter"]);
const ADDING = new Set(["new-export", "optional-input-property", "wider-parameter"]);

function releaseFor(changes: Change[]): "major" | "minor" | "patch" {
  if (changes.some((c) => BREAKING.has(c))) return "major";
  if (changes.some((c) => ADDING.has(c))) return "minor";
  return "patch";
}

console.log(releaseFor(["docs", "new-export"]));
console.log(releaseFor(["optional-input-property", "wider-return"]));
console.log(releaseFor(["docs"]));
