const BRAND = Symbol.for("@naija-shop/payment-error");

function loadPaymentsModule() {
  class PaymentError extends Error {
    readonly code: string;
    readonly [BRAND] = true;
    constructor(code: string) {
      super(code);
      this.code = code;
    }
  }
  function isPaymentError(error: unknown): boolean {
    return typeof error === "object" && error !== null && (error as Record<symbol, unknown>)[BRAND] === true;
  }
  return { PaymentError, isPaymentError };
}

const esm = loadPaymentsModule();
const cjs = loadPaymentsModule();
console.log(esm.isPaymentError(new cjs.PaymentError("card_declined")));
console.log(esm.isPaymentError(new Error("card_declined")));

