function nextVersion(version: string, release: "major" | "minor" | "patch"): string {
  const [major, minor, patch] = version.split(".").map(Number);
  if (release === "major") return `${major + 1}.0.0`;
  if (release === "minor") return `${major}.${minor + 1}.0`;
  return `${major}.${minor}.${patch + 1}`;
}

console.log(nextVersion("1.0.1", "patch"), nextVersion("1.0.1", "minor"), nextVersion("1.9.4", "major"));
console.log(nextVersion("1.9.0", "minor"));

