questions.solution:
function supports(required: string, running: string): boolean {
  const minimum = Number(required.replace(">=", ""));
  const major = Number(running.replace(/^v/, "").split(".")[0]);
  return major >= minimum;
}

for (const running of ["v24.19.0", "22.12.0", "v26.0.1"]) {
  console.log(running, supports(">=24", running));
}
